<script setup lang="ts">
import {computed,ref,onBeforeUnmount} from "vue";
import {NButton,NInput,NSelect,NSlider,NSwitch,NTabs,NTabPane,NModal,NEmpty,NAlert,NPagination,NCollapse,NCollapseItem,NColorPicker,NSpin} from "naive-ui";
import {invoke,type WallpaperLibrary,type WallpaperOptions} from "../../bridge.ts";
import {siteMedia} from "../../wallpaper-media.ts";
import type {ControlStore} from "../control-types.ts";
import {useWallpaperWorkspace,type Selection,type SelectedEffect} from "../wallpaper/useWallpaperWorkspace.ts";
import MediaPreview from "../wallpaper/MediaPreview.vue";
import {createWallpaperContextMenu,type ContextAction} from "../wallpaper/context-menu.ts";
const props=defineProps<{store:ControlStore}>();
const {progress,progressPercent,saved,tab,media,query,category,page,localSource,selection,draft,busy,loading,error,feed,categories,kind,selectedEffect,setEffect,select,cancel,load,localItems,action}=useWallpaperWorkspace(props.store);
const advanced=ref(false),subscription=ref(props.store.settings.catalogUrl),advancedBusy=ref(false),file=ref<HTMLInputElement>();
const current=computed(()=>selection.value?.source==='local'?selection.value.item.definition:null);
const title=computed(()=>selection.value?.source==='local'?selection.value.item.definition.title:selection.value?.item.title || '');
const cards=computed<Selection[]>(()=>tab.value==='online'?feed.items.map(item=>({source:'online',item})):localItems.value.map(item=>({source:'local',item})));
const cardId=(card:Selection)=>card.source==='local'?card.item.definition.id:card.item.id;
const cardTitle=(card:Selection)=>card.source==='local'?card.item.definition.title:card.item.title;
const cardKind=(card:Selection)=>card.source==='local'?card.item.definition.kind:card.item.media_type;
const sources=(card:Selection)=>card.source==='online'?siteMedia(card.item,props.store.settings.websiteUrl):{poster:card.item.coverUrl || (card.item.definition.kind==='image'?card.item.previewUrl || '':''),video:card.item.previewUrl || ''};
const preview=computed(()=>selection.value?sources(selection.value):{poster:'',video:''});
const effect=computed(()=>selectedEffect.value==='none'?null:draft.value.effects[selectedEffect.value as SelectedEffect & keyof typeof draft.value.effects]);
const types=[{label:'全部类型',value:''},{label:'图片',value:'image'},{label:'视频',value:'video'},{label:'互动动画',value:'canvas'}];
const fits=[{label:'铺满屏幕',value:'cover'},{label:'完整显示',value:'contain'},{label:'拉伸适配',value:'fill'}];
const effects=[{label:'无特效',value:'none'},{label:'下雨',value:'rain'},{label:'下雪',value:'snow'},{label:'萤火虫',value:'fireflies'}];
async function importMedia(){try {const id=await props.store.importMedia();if(id){tab.value='local';localSource.value='local';const item=props.store.library.items.find(e=>e.definition.id===id);if(item)select({source:'local',item});}}catch(e){props.store.notify(e,'error');}}
async function advancedAction(command:string,args?:Record<string,unknown>){advancedBusy.value=true;try{if(!props.store.desktop)throw new Error('请在桌面应用中使用订阅与清单');props.store.library=await invoke<WallpaperLibrary>(command,args);await props.store.refreshSettings();props.store.notify('壁纸库已更新','success');}catch(e){props.store.notify(e,'error');}finally{advancedBusy.value=false;}}
async function importJson(event:Event){const input=event.target as HTMLInputElement;const selected=input.files?.[0];if(!selected)return;try{if(selected.size>1024*1024)throw new Error('清单不能超过 1 MB');await advancedAction('import_wallpaper_catalog',{text:await selected.text()});}catch(e){props.store.notify(e,'error');}finally{input.value='';}}
async function refreshSubscription(){const url=props.store.library.source;if(!url){props.store.notify("尚未添加订阅，请先填写订阅地址","info");return;}await advancedAction("subscribe_wallpapers",{url});}
function setFit(value:string){if(busy.value)return;draft.value.fit=value as WallpaperOptions['fit'];}

const nativeContext=createWallpaperContextMenu();
const context=ref<{x:number;y:number;card:Selection;items:ContextAction[]} | null>(null);
function contextActions(card:Selection):ContextAction[]{
  const items:ContextAction[]=[{key:'inspect',label:'预览与设置'},{key:'apply',label:'应用到桌面',disabled:busy.value}];
  if(card.source==='online')items.push({key:'save',label:saved.value?'已保存到我的壁纸':'保存到我的壁纸',disabled:busy.value||saved.value});
  if(cardKind(card)==='canvas')items.push({key:'preview',label:'独立窗口预览',disabled:busy.value});
  return items;
}
function chooseContext(key:string){
  context.value=null;
  if(key==='apply')void action(true);
  else if(key==='save')void action(false);
  else if(key==='preview')void action(true,true);
}
async function openContext(event:MouseEvent,card:Selection){
  if(busy.value)return;
  const selected=selection.value;
  if(!selected||selected.source!==card.source||cardId(selected)!==cardId(card))select(card);
  const items=contextActions(card);
  try{if(props.store.desktop&&await nativeContext.show(items,chooseContext))return;}
  catch(e){props.store.notify(e,'error');}
  context.value={x:Math.max(4,Math.min(event.clientX,window.innerWidth-214)),y:Math.max(4,Math.min(event.clientY,window.innerHeight-items.length*34-16)),card,items};
}
onBeforeUnmount(()=>nativeContext.dispose());
</script>
<template>
<section class="ui-page wallpaper-workbench" data-testid="wallpapers-page">
<div class="workbench-tools">
<div class="source-row"><NTabs v-model:value="tab" type="line" size="small"><NTabPane name="online" :disabled="busy"><template #tab>在线资源</template></NTabPane><NTabPane name="local" :disabled="busy"><template #tab>我的壁纸</template></NTabPane></NTabs><div class="source-actions"><NButton size="small" data-testid="import-media" :disabled="busy" @click="importMedia">导入图片 / 视频</NButton><NButton size="small" :disabled="busy" @click="advanced=true">订阅与清单</NButton></div></div>
<div class="toolbar"><NInput size="small" :disabled="busy" v-model:value="query" clearable placeholder="搜索素材" data-testid="wallpaper-search" @keyup.enter="page=1;load()"/><NSelect size="small" :disabled="busy" v-model:value="media" :options="tab==='online'?types.filter(type=>type.value!=='canvas'):types" aria-label="壁纸类型"/><NSelect size="small" :disabled="busy" v-if="tab==='online'" v-model:value="category" :options="[{label:'全部分类',value:''},...categories.map(c=>({label:c.name,value:c.id}))]" aria-label="分类"/><NSelect size="small" :disabled="busy" v-else v-model:value="localSource" :options="[{label:'全部来源',value:''},{label:'我的导入',value:'local'},{label:'内置壁纸',value:'builtin'},{label:'订阅壁纸',value:'subscription'}]" aria-label="本地来源"/><NButton size="small" :disabled="busy" v-if="tab==='online'" @click="page=1;load()">搜索</NButton></div>
</div>
<NAlert v-if="error" type="error" class="feed-alert">{{error}}<NButton size="small" @click="load">重试</NButton></NAlert>
<NAlert v-if="tab==='online'&&!store.desktop" type="info">在线资源需要桌面应用连接真实网站。浏览器预览可查看我的壁纸。</NAlert>
<div class="workspace" :class="{'has-selection':selection}"><div class="gallery-area"><div class="gallery-scroll"><NSpin :show="loading"><div class="gallery"><button v-for="card in cards" :key="card.source+cardId(card)" class="wallpaper-card" :disabled="busy" :class="{selected:selection&&cardId(selection)===cardId(card)&&selection.source===card.source}" :data-testid="'wallpaper-card-'+cardId(card)" @click="select(card)" @contextmenu.prevent="openContext($event,card)"><div class="card-cover"><MediaPreview :kind="cardKind(card)" :source="sources(card).video" :poster="sources(card).poster" :title="cardTitle(card)"/><span class="type-badge">{{cardKind(card)==='video'?'视频':cardKind(card)==='canvas'?'动画':'图片'}}</span></div><div class="card-info"><strong>{{cardTitle(card)}}</strong><span class="muted">{{card.source==='online'?card.item.author.name:card.item.installed?'本地可用':'订阅资源'}}</span></div></button></div><NEmpty v-if="!cards.length&&!loading" :description="tab==='online'?'暂无匹配的在线资源':'还没有这一类壁纸'" class="empty-state"/></NSpin></div><div class="gallery-footer"><div v-if="tab==='online'" class="pagination"><span class="muted">共 {{feed.total}} 张</span><NPagination :disabled="busy" :page="page" :page-count="page+(feed.has_more?1:0)" @update:page="page=$event"/></div><p v-else class="gallery-note muted">{{cards.length}} 个素材</p></div></div>
<aside v-if="selection" class="inspector" data-testid="wallpaper-inspector"><div class="inspector-heading"><span class="muted">预览与设置</span><NButton text data-testid="cancel-selection" :disabled="busy" @click="cancel">取消选择</NButton></div><div class="inspector-scroll" data-testid="inspector-scroll"><div class="inspector-preview"><MediaPreview :key="selection.source+cardId(selection)" :kind="kind || ''" :source="preview.video" :poster="preview.poster" :title="title" controls :fit="draft.fit" :rate="draft.playbackRate" :effects="draft.effects" :paused="store.settings.paused" :fps="store.settings.fps"/></div><h2>{{title}}</h2><p class="muted">{{selection.source==='local'?selection.item.definition.description:selection.item.description}}</p><div class="draft-note">修改后点击“应用到桌面”生效。</div>
<div v-if="kind!=='canvas'" class="field"><label>画面适配</label><NSelect :disabled="busy" :value="draft.fit" :options="fits" data-testid="wallpaper-fit" @update:value="setFit"/></div><div v-if="kind==='video'" class="field"><label>播放速度 <span>{{draft.playbackRate}}×</span></label><NSlider :disabled="busy" v-model:value="draft.playbackRate" :min="0.25" :max="2" :step="0.25"/><small class="muted">静音循环播放</small></div>
<div class="field"><label>画面特效</label><NSelect :value="selectedEffect" :options="effects" :disabled="busy || kind==='canvas'" data-testid="wallpaper-effect" @update:value="setEffect"/><small v-if="kind==='canvas'" class="muted">互动动画暂不支持叠加特效，参数会保留。</small></div><template v-if="kind!=='canvas'&&effect"><div class="field"><label>强度 <span>{{Math.round(effect.intensity*100)}}%</span></label><NSlider :disabled="busy" v-model:value="effect.intensity" :min="0" :max="1" :step="0.05"/></div><div class="field"><label>速度 <span>{{effect.speed}}×</span></label><NSlider :disabled="busy" v-model:value="effect.speed" :min="0.25" :max="3" :step="0.25"/></div></template>
<NCollapse v-if="current?.controls?.length"><NCollapseItem title="动画参数" name="controls"><div v-for="control in current.controls" :key="control.key" class="field"><label>{{control.label}}</label><NSlider :disabled="busy" v-if="control.type==='range'" :value="Number(draft.values[control.key])" :min="control.min" :max="control.max" :step="control.step" @update:value="draft.values[control.key]=$event"/><NSwitch :disabled="busy" v-else-if="control.type==='boolean'" :value="Boolean(draft.values[control.key])" @update:value="draft.values[control.key]=$event"/><NColorPicker :disabled="busy" v-else-if="control.type==='color'" :value="String(draft.values[control.key])" :show-alpha="false" @update:value="draft.values[control.key]=$event"/><NSelect :disabled="busy" v-else :value="String(draft.values[control.key])" :options="(control.options||[]).map(value=>({label:value,value}))" @update:value="draft.values[control.key]=$event"/></div></NCollapseItem></NCollapse>
</div><footer class="inspector-actions" data-testid="inspector-actions"><div v-if="busy" class="download-feedback" role="status" data-testid="wallpaper-progress"><span>{{progressPercent===null ? "正在准备壁纸文件…" : progressPercent>=100 ? "下载完成，正在校验 / 应用…" : `正在下载 ${progressPercent}%`}}</span><progress v-if="progress" max="100" :value="progressPercent || 0"/><progress v-else max="100"/></div><div class="actions"><NButton v-if="selection.source==='online'" block :loading="busy" :disabled="saved || busy" data-testid="save-wallpaper" @click="action(false)">{{saved?'已保存到我的壁纸':'保存到我的壁纸'}}</NButton><NButton v-if="kind==='canvas'" block :disabled="busy" @click="action(true,true)">独立窗口预览</NButton><NButton type="primary" block :loading="busy" data-testid="apply-wallpaper" :disabled="busy" @click="action(true)">应用到桌面</NButton></div></footer></aside>
<aside v-else class="inspector-placeholder"><h3>未选择素材</h3><p class="muted">选择素材以查看预览与属性。</p></aside></div>
<NModal v-model:show="advanced" preset="card" title="订阅与清单" class="advanced-modal" style="width:min(520px,90vw)"><p class="muted">订阅 HTTPS 清单，或导入已有的 JSON 壁纸清单。</p><div class="field"><label>订阅地址</label><NInput :disabled="busy" v-model:value="subscription" placeholder="https://…/wallpapers.json"/></div><div class="advanced-actions"><NButton :loading="advancedBusy" type="primary" @click="advancedAction('subscribe_wallpapers',{url:subscription})">添加订阅</NButton><NButton data-testid="refresh-subscription" :disabled="advancedBusy" @click="refreshSubscription">刷新订阅</NButton><NButton @click="file?.click()">导入 JSON</NButton></div><input ref="file" type="file" accept=".json,application/json" hidden @change="importJson"/></NModal>
<Teleport to="body"><template v-if="context"><div class="context-dismiss" @pointerdown="context=null" @contextmenu.prevent="context=null"></div><div class="material-context" role="menu" data-testid="material-context-menu" :style="{left:context.x+'px',top:context.y+'px'}" @keydown.esc="context=null"><button v-for="item in context.items" :key="item.key" role="menuitem" :disabled="item.disabled" @click="chooseContext(item.key)">{{item.label}}</button></div></template></Teleport>
</section>
</template>
<style scoped>
.wallpaper-workbench{height:100%;width:100%;max-width:none;min-height:0;margin:0;display:flex;flex-direction:column;overflow:hidden}
.workbench-tools{flex:none;background:#fff;border-bottom:1px solid var(--ui-line);padding:0 14px 12px}
.source-row{height:42px;display:flex;align-items:center;gap:20px}.source-row>.n-tabs{width:210px;flex:none}.source-row :deep(.n-tab-pane){display:none}.source-actions{margin-left:auto;display:flex;gap:8px}.toolbar{display:flex;align-items:center;gap:8px}.toolbar>.n-input{width:220px;flex:none}.toolbar>.n-select{width:130px;flex:none}
.workspace{display:grid;grid-template-columns:minmax(0,1fr) 320px;flex:1;min-height:0;overflow:hidden}
.gallery-area{display:flex;flex-direction:column;min-height:0;min-width:0}.gallery-scroll{flex:1;min-height:0;overflow:auto;padding:14px;overscroll-behavior:none;scroll-behavior:auto}
.gallery{display:grid;grid-template-columns:repeat(auto-fill,160px);align-content:start;gap:12px}.wallpaper-card{width:160px;text-align:left;padding:0;border:1px solid #dce3ec;background:#fff;border-radius:3px;overflow:hidden;cursor:pointer;color:#25334a;transition:none}.wallpaper-card:hover{border-color:#9db5d7;background:#f8fbff}.wallpaper-card.selected{border-color:#2563eb;outline:2px solid #2563eb;outline-offset:0;background:#edf4ff}.card-cover{height:100px;position:relative}.type-badge{position:absolute;right:5px;bottom:5px;background:#142136b0;color:white;border-radius:2px;padding:1px 5px;font-size:10px}.card-info{padding:8px;display:grid;gap:4px}.card-info strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.card-info span{font-size:10px}
.gallery-footer{flex:none;min-height:36px;padding:6px 14px;border-top:1px solid var(--ui-line);background:#fff}.pagination{display:flex;align-items:center;justify-content:space-between;font-size:11px}.gallery-note{font-size:11px;margin:2px 0}
.inspector,.inspector-placeholder{border-left:1px solid var(--ui-line);background:#fff;min-width:0;min-height:0;overflow:hidden}.inspector{display:flex;flex-direction:column}.inspector-heading{height:40px;flex:none;display:flex;justify-content:space-between;align-items:center;padding:0 14px;border-bottom:1px solid var(--ui-line);font-size:12px}.inspector-scroll{flex:1;min-height:0;overflow:auto;padding:14px;overscroll-behavior:none;scroll-behavior:auto}.inspector-preview{height:174px;overflow:hidden;background:#f2f5f9;border:1px solid var(--ui-line);border-radius:3px}.inspector h2{font-size:15px;margin:12px 0 6px}.inspector-scroll>p{font-size:11px;color:var(--ui-muted);line-height:1.6;margin:0;max-height:35px;overflow:hidden}.draft-note{font-size:11px;color:#8793a5;margin:10px 0}.field{margin:12px 0}.field>label{display:flex;justify-content:space-between;font-size:12px;font-weight:500;margin-bottom:7px}.field small{font-size:10px}.inspector-actions{flex:none;padding:12px 14px;background:#fff;border-top:1px solid var(--ui-line)}.actions{display:grid;gap:8px}.download-feedback{display:grid;gap:6px;margin-bottom:10px;color:#5176a5;font-size:11px}.download-feedback progress{width:100%;height:5px;accent-color:#2563eb}.inspector-placeholder{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;text-align:center}.inspector-placeholder h3{font-size:14px;font-weight:500;margin:0 0 8px}.inspector-placeholder p{font-size:11px;margin:0}.feed-alert{flex:none;max-height:84px;overflow:auto;border-radius:0}.advanced-actions{display:flex;gap:8px}
.context-dismiss{position:fixed;inset:0;z-index:3000}.material-context{position:fixed;z-index:3001;width:210px;padding:4px;background:#fff;border:1px solid #c9d1de;border-radius:3px;box-shadow:0 3px 12px #172c4d28;font-size:12px}.material-context button{display:block;width:100%;height:32px;border:0;border-radius:2px;background:none;text-align:left;padding:0 10px;color:#293951;cursor:pointer;font:inherit}.material-context button:hover{background:#eaf2ff}.material-context button:disabled{color:#a1aab8;cursor:default}
</style>
